//! Pseudo-locale `qps` (L5): every English text with accented letters,
//! about 40 % longer (short texts more) and in brackets, so layouts that
//! break with longer translations show it before a real translation
//! exists. `lang/qps` is generated by the `extract` tool (never by hand).

use crate::extract::{merge, Found};
use crate::po::Catalog;

/// Code of the pseudo-locale (gettext's “qps-ploc” family).
pub const CODE: &str = "qps";

/// Letters with an accented look-alike (Latin-1 and Latin Extended-A only:
/// Segoe UI and the Linux fonts have them).
fn accent(c: char) -> char {
    match c {
        'a' => 'å',
        'c' => 'ç',
        'd' => 'ď',
        'e' => 'é',
        'g' => 'ğ',
        'i' => 'î',
        'l' => 'ł',
        'n' => 'ñ',
        'o' => 'ö',
        'r' => 'ř',
        's' => 'š',
        't' => 'ť',
        'u' => 'ü',
        'y' => 'ý',
        'z' => 'ž',
        'A' => 'Å',
        'C' => 'Ç',
        'D' => 'Ď',
        'E' => 'É',
        'G' => 'Ğ',
        'I' => 'Î',
        'L' => 'Ł',
        'N' => 'Ñ',
        'O' => 'Ö',
        'R' => 'Ř',
        'S' => 'Š',
        'T' => 'Ť',
        'U' => 'Ü',
        'Y' => 'Ý',
        'Z' => 'Ž',
        c => c,
    }
}

/// Extra characters for a text of `len` visible characters: German,
/// French or Russian labels often grow by half, long sentences by a third.
pub fn growth(len: usize) -> usize {
    match len {
        0 => 0,
        1..=10 => len.div_ceil(2).max(2),
        _ => (len * 2).div_ceil(5),
    }
}

/// `Copy {0} files` → `[Çöpý {0} fîłéš·······]`; placeholders (`{…}`) and
/// line breaks stay, every line is padded on its own.
pub fn pseudo(text: &str) -> String {
    if text.is_empty() {
        return String::new();
    }
    let lines: Vec<String> = text.split('\n').map(pseudo_line).collect();
    format!("[{}]", lines.join("\n"))
}

fn pseudo_line(line: &str) -> String {
    let mut out = String::new();
    let mut visible = 0;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '{' {
            // a placeholder or an escaped brace: copied as it is
            out.push(c);
            if chars.peek() == Some(&'{') {
                out.push(chars.next().unwrap_or('{'));
                continue;
            }
            for d in chars.by_ref() {
                out.push(d);
                if d == '}' {
                    break;
                }
            }
            visible += 4; // a number or a name will stand there
            continue;
        }
        out.push(accent(c));
        // an access-key marker (`&Replace`) is not shown: same padding as `Replace`
        if c != '&' {
            visible += 1;
        }
    }
    out.extend(std::iter::repeat_n('·', growth(visible)));
    out
}

/// The whole `qps` catalog for the texts in the code.
pub fn catalog(found: &Found) -> Catalog {
    let mut cat = merge(None, found, CODE);
    for e in &mut cat.entries {
        let forms = e.strs.len();
        e.strs = (0..forms)
            .map(|i| match (&e.id_plural, i) {
                (Some(p), i) if i > 0 => pseudo(p),
                _ => pseudo(&e.id),
            })
            .collect();
        e.comments
            .retain(|c| !c.starts_with("#,") && !c.starts_with("# "));
    }
    cat
}
